```javascript
function validateOrderPayload(orderPayload) {
  if (!orderPayload || !orderPayload.userId || !Array.isArray(orderPayload.items) || orderPayload.items.length === 0) {
    return { success: false, code: 'INVALID_PAYLOAD', error: 'User ID and items array required' };
  }
  for (const it of orderPayload.items) {
    if (!it.sku || typeof it.qty !== 'number' || it.qty <= 0 || typeof it.price !== 'number' || it.price < 0) {
      return { success: false, code: 'INVALID_ITEM', error: `Invalid item: ${JSON.stringify(it)}` };
    }
  }
  return null;
}

async function calculateDiscount(subtotal, couponCode, db) {
  if (!couponCode) return 0;
  const coupon = await db.collection('coupons').findOne({ code: couponCode, active: true });
  if (!coupon) return 0;
  if (coupon.type === 'percent') return subtotal * (coupon.amount / 100);
  if (coupon.type === 'fixed') return Math.min(subtotal, coupon.amount);
  return 0;
}

function calculateTotals(subtotal, discount) {
  const taxRate = 0.0925;
  const taxable = Math.max(0, subtotal - discount);
  const tax = taxable * taxRate;
  const shipping = subtotal > 100 ? 0 : 9.99;
  const total = Math.round((taxable + tax + shipping) * 100) / 100;
  return { tax, shipping, total };
}

async function checkInventory(items, db) {
  for (const it of items) {
    const inv = await db.collection('inventory').findOne({ sku: it.sku });
    if (!inv || inv.stock < it.qty) {
      return { success: false, code: 'OUT_OF_STOCK', error: `Out of stock for ${it.sku}` };
    }
  }
  return null;
}

async function processPayment(orderPayload, total, paymentGateway) {
  try {
    return await paymentGateway.charge({
      customerId: orderPayload.userId,
      amount: Math.round(total * 100),
      currency: 'usd',
      idempotencyKey: orderPayload.idempotencyKey,
    });
  } catch (err) {
    return { error: err.message };
  }
}

async function persistOrder(orderPayload, orderRecord, db) {
  const insertResult = await db.collection('orders').insertOne(orderRecord);
  for (const it of orderPayload.items) {
    await db.collection('inventory').updateOne({ sku: it.sku }, { $inc: { stock: -it.qty } });
  }
  return insertResult;
}

async function sendConfirmationEmail(orderPayload, total, insertedId, emailClient) {
  try {
    await emailClient.send({
      to: orderPayload.customerEmail,
      subject: `Order Confirmation #${insertedId}`,
      body: `Thank you for your order of $${total.toFixed(2)}.`,
    });
  } catch (emailErr) {
    console.error('Failed to send confirmation email', emailErr);
  }
}

async function processOrder(orderPayload, db, paymentGateway, emailClient) {
  const validationError = validateOrderPayload(orderPayload);
  if (validationError) return validationError;

  let subtotal = 0;
  for (const it of orderPayload.items) subtotal += it.price * it.qty;

  const discount = await calculateDiscount(subtotal, orderPayload.couponCode, db);
  const { tax, shipping, total } = calculateTotals(subtotal, discount);

  const inventoryError = await checkInventory(orderPayload.items, db);
  if (inventoryError) return inventoryError;

  const paymentResult = await processPayment(orderPayload, total, paymentGateway);
  if (paymentResult.error) {
    return { success: false, code: 'PAYMENT_FAILED', error: paymentResult.error };
  }

  const orderRecord = {
    userId: orderPayload.userId,
    items: orderPayload.items,
    subtotal,
    discount,
    tax,
    shipping,
    total,
    chargeId: paymentResult.chargeId,
    createdAt: new Date(),
    status: 'PAID',
  };
  const insertResult = await persistOrder(orderPayload, orderRecord, db);

  await sendConfirmationEmail(orderPayload, total, insertResult.insertedId, emailClient);

  return { success: true, orderId: insertResult.insertedId, total };
}
```

Each extracted function has a single, clearly named responsibility:

| Function | Responsibility |
|---|---|
| `validateOrderPayload` | Structural validation of payload and every item |
| `calculateDiscount` | Coupon lookup and discount amount |
| `calculateTotals` | Tax, shipping, and grand total from subtotal/discount |
| `checkInventory` | Sufficient stock for all items |
| `processPayment` | Payment gateway charge |
| `persistOrder` | Order insert + inventory decrement |
| `sendConfirmationEmail` | Confirmation email (non-fatal on failure) |
| `processOrder` | Orchestration of the above |

Behavior is unchanged: same validation order, same error codes, same rounding, same side-effects.

