export function compactDedupe<T>(items: T[] | null | undefined): T[] {
  if (!items || !Array.isArray(items)) return [];
  const set = new Set<T>();
  const out: T[] = [];
  for (const item of items) {
    if (item !== null && item !== undefined && !set.has(item)) {
      set.add(item);
      out.push(item);
    }
  }
