  if (!forceRefresh && userCache[userId] && (now - lastFetchTime < 60000)) {
    return userCache[userId];
  }

  try {
    const res = await fetch('https://api.internal/v1/users/' + userId);
    const data = await res.json();
    userCache[userId] = data;
